1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  :root { --cell: 28px; }
9	  * { box-sizing: border-box; }
10	  body {
11	    margin: 0; min-height: 100vh; display: flex; align-items: center; justify-content: center;
12	    background: #14161c; color: #e8e8ec; font: 15px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
13	  }
14	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; flex-wrap: wrap; justify-content: center; }
15	  .board {
16	    display: grid; grid-template-columns: repeat(10, var(--cell)); grid-template-rows: repeat(20, var(--cell));
17	    gap: 1px; padding: 1px; background: #262a33; border: 2px solid #3a3f4b; border-radius: 4px;
18	  }
19	  .cell { width: var(--cell); height: var(--cell); background: #0d0f14; }
20	  .cell[data-filled="true"] { box-shadow: inset 0 0 0 2px rgba(255,255,255,0.18), inset 0 -3px 0 rgba(0,0,0,0.25); }
21	  .panel { display: flex; flex-direction: column; gap: 14px; min-width: 150px; }
22	  .stat { background: #1c1f27; border: 1px solid #2c313c; border-radius: 6px; padding: 8px 12px; }
23	  .stat .label { font-size: 12px; text-transform: uppercase; letter-spacing: 0.08em; color: #9097a6; }
24	  .stat .value { font-size: 22px; font-weight: 600; font-variant-numeric: tabular-nums; }
25	  .preview { display: grid; grid-template-columns: repeat(4, 20px); grid-template-rows: repeat(2, 20px); gap: 1px; margin-top: 6px; }
26	  .preview .mini { width: 20px; height: 20px; background: transparent; }
27	  .preview .mini[data-filled="true"] { box-shadow: inset 0 0 0 2px rgba(255,255,255,0.18); }
28	  .status { min-height: 1.4em; color: #ff8a80; font-weight: 600; }
29	  .help { font-size: 13px; color: #9097a6; }
30	  .help kbd { background: #2c313c; border-radius: 3px; padding: 0 5px; color: #e8e8ec; font: inherit; }
31	  button {
32	    background: #3a6ff7; color: #fff; border: 0; border-radius: 6px; padding: 8px 12px;
33	    font: inherit; font-weight: 600; cursor: pointer;
34	  }
35	</style>
36	</head>
37	<body>
38	<div class="game">
39	  <div class="board" data-testid="board"></div>
40	  <div class="panel">
41	    <div class="stat"><div class="label">Score</div><div class="value" data-testid="score">0</div></div>
42	    <div class="stat"><div class="label">Level</div><div class="value" data-testid="level">1</div></div>
43	    <div class="stat"><div class="label">Lines</div><div class="value" data-testid="lines">0</div></div>
44	    <div class="stat"><div class="label">Next</div><div class="preview" data-testid="next"></div></div>
45	    <div class="status" data-testid="status"></div>
46	    <button type="button" id="new-game">New game</button>
47	    <div class="help">
48	      <kbd>←</kbd> <kbd>→</kbd> move<br>
49	      <kbd>↑</kbd> rotate<br>
50	      <kbd>↓</kbd> soft drop<br>
51	      <kbd>Space</kbd> hard drop
52	    </div>
53	  </div>
54	</div>
55	<script>
56	(function () {
57	  'use strict';
58	
59	  var ROWS = 20, COLS = 10;
60	  var TYPES = ['I', 'O', 'T', 'S', 'Z', 'J', 'L'];
61	  var COLORS = {
62	    I: '#00bcd4', O: '#f5c400', T: '#9c27b0', S: '#43a047',
63	    Z: '#e53935', J: '#1e63d6', L: '#fb8c00'
64	  };
65	  // Spawn orientation, as [row, col] offsets from the piece origin.
66	  var SHAPES = {
67	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
68	    O: [[0, 0], [0, 1], [1, 0], [1, 1]],
69	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
70	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
71	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
72	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
73	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
74	  };
75	  var SPAWN_COL = { I: 3, O: 4, T: 3, S: 3, Z: 3, J: 3, L: 3 };
76	  var GRAVITY_MS = 1000;
77	
78	  // Clockwise rotation states. Each is a quarter turn of the one before, inside the
79	  // piece's box (2x2 for O, 3x3 for the rest). I is listed by hand so it turns about its middle.
80	  var ROTATIONS = {};
81	  TYPES.forEach(function (t) {
82	    var n = t === 'O' ? 2 : 3;
83	    var states = [SHAPES[t]];
84	    for (var k = 1; k < 4; k++) {
85	      states.push(states[k - 1].map(function (p) { return [p[1], n - 1 - p[0]]; }));
86	    }
87	    ROTATIONS[t] = states;
88	  });
89	  ROTATIONS.I = [
90	    SHAPES.I,
91	    [[0, 2], [1, 2], [2, 2], [3, 2]],
92	    [[1, 0], [1, 1], [1, 2], [1, 3]],
93	    [[0, 1], [1, 1], [2, 1], [3, 1]]
94	  ];
95	  // Sideways shifts tried, in order, when a rotated piece does not fit where it is.
96	  var KICKS = [0, -1, 1, -2, 2];
97	
98	  // Locking rule (a project decision): a gravity step that cannot move the piece down counts
99	  // one tick of lock delay; the piece locks on the LOCK_TICKS-th such tick. A successful left or
100	  // right move during the delay restarts it, at most MAX_RESTARTS times per piece. Hard drop
101	  // locks at once.
102	  var LOCK_TICKS = 2;
103	  var MAX_RESTARTS = 3;
104	
105	  // Scoring rule (a project decision): a clear scores LINE_POINTS[rows cleared at once] times the
106	  // current level. Clearing rows together must always beat clearing the same rows in smaller
107	  // groups, so every entry must exceed any sum of smaller entries that adds up to the same rows.
108	  // Soft drop scores 1 per cell moved down by the player; hard drop scores 2 per cell dropped.
109	  var LINE_POINTS = [0, 100, 300, 500, 800];
110	  var SOFT_DROP_POINTS = 1;
111	  var HARD_DROP_POINTS = 2;
112	
113	  // Game state. `board` holds the locked cells: a piece letter, or '' when empty.
114	  var board, current, queue, bag, score, level, lines, status, timer = null;
115	
116	  // ---- DOM ----
117	  var boardEl = document.querySelector('[data-testid="board"]');
118	  var scoreEl = document.querySelector('[data-testid="score"]');
119	  var levelEl = document.querySelector('[data-testid="level"]');
120	  var linesEl = document.querySelector('[data-testid="lines"]');
121	  var nextEl = document.querySelector('[data-testid="next"]');
122	  var statusEl = document.querySelector('[data-testid="status"]');
123	  var cellEls = [];
124	  var miniEls = [];
125	
126	  for (var r = 0; r < ROWS; r++) {
127	    cellEls.push([]);
128	    for (var c = 0; c < COLS; c++) {
129	      var el = document.createElement('div');
130	      el.className = 'cell';
131	      el.setAttribute('data-testid', 'cell');
132	      el.setAttribute('data-row', String(r));
133	      el.setAttribute('data-col', String(c));
134	      boardEl.appendChild(el);
135	      cellEls[r].push(el);
136	    }
137	  }
138	  for (var mr = 0; mr < 2; mr++) {
139	    miniEls.push([]);
140	    for (var mc = 0; mc < 4; mc++) {
141	      var m = document.createElement('div');
142	      m.className = 'mini';
143	      nextEl.appendChild(m);
144	      miniEls[mr].push(m);
145	    }
146	  }
147	
148	  function paint(el, type) {
149	    el.setAttribute('data-filled', type ? 'true' : 'false');
150	    el.setAttribute('data-piece', type || '');
151	    el.style.backgroundColor = type ? COLORS[type] : '';
152	  }
153	
154	  function render() {
155	    var view = board.map(function (row) { return row.slice(); });
156	    if (current) {
157	      pieceCells(current).forEach(function (p) { view[p[0]][p[1]] = current.type; });
158	    }
159	    for (var r = 0; r < ROWS; r++) {
160	      for (var c = 0; c < COLS; c++) paint(cellEls[r][c], view[r][c]);
161	    }
162	
163	    var upcoming = queue[0] || '';
164	    for (var mr = 0; mr < 2; mr++) {
165	      for (var mc = 0; mc < 4; mc++) paint(miniEls[mr][mc], '');
166	    }
167	    if (upcoming) {
168	      SHAPES[upcoming].forEach(function (p) { paint(miniEls[p[0]][p[1]], upcoming); });
169	    }
170	
171	    scoreEl.textContent = String(score);
172	    levelEl.textContent = String(level);
173	    linesEl.textContent = String(lines);
174	    statusEl.textContent = status === 'over' ? 'Game over' : '';
175	  }
176	
177	  // ---- Pieces ----
178	  function randomPiece() {
179	    if (!bag.length) {
180	      bag = TYPES.slice();
181	      for (var i = bag.length - 1; i > 0; i--) {
182	        var j = Math.floor(Math.random() * (i + 1));
183	        var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
184	      }
185	    }
186	    return bag.pop();
187	  }
188	
189	  function takeNext() {
190	    if (!queue.length) queue.push(randomPiece());
191	    var type = queue.shift();
192	    if (!queue.length) queue.push(randomPiece());
193	    return type;
194	  }
195	
196	  function pieceCells(piece) {
197	    return ROTATIONS[piece.type][piece.rot].map(function (p) { return [piece.row + p[0], piece.col + p[1]]; });
198	  }
199	
200	  function fits(cells) {
201	    return cells.every(function (p) {
202	      return p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS && !board[p[0]][p[1]];
203	    });
204	  }
205	
206	  function spawn() {
207	    var type = takeNext();
208	    var piece = { type: type, row: 0, col: SPAWN_COL[type], rot: 0, lockTicks: 0, restarts: 0 };
209	    if (!fits(pieceCells(piece))) {
210	      current = null;
211	      status = 'over';
212	      stopTimer();
213	      return;
214	    }
215	    current = piece;
216	  }
217	
218	  function move(dr, dc) {
219	    if (!current) return false;
220	    var moved = { type: current.type, row: current.row + dr, col: current.col + dc, rot: current.rot };
221	    if (!fits(pieceCells(moved))) return false;
222	    current.row = moved.row;
223	    current.col = moved.col;
224	    return true;
225	  }
226	
227	  // Left or right. During the lock delay, a successful move restarts it, up to the cap.
228	  function shift(dc) {
229	    if (!move(0, dc)) return;
230	    if (current.lockTicks > 0 && current.restarts < MAX_RESTARTS) {
231	      current.lockTicks = 0;
232	      current.restarts++;
233	    }
234	  }
235	
236	  // Try the next clockwise state in place, then shifted sideways. If nothing fits, change nothing.
237	  function rotateCW() {
238	    if (!current) return false;
239	    var rot = (current.rot + 1) % 4;
240	    for (var i = 0; i < KICKS.length; i++) {
241	      var turned = { type: current.type, row: current.row, col: current.col + KICKS[i], rot: rot };
242	      if (fits(pieceCells(turned))) {
243	        current.col = turned.col;
244	        current.rot = rot;
245	        return true;
246	      }
247	    }
248	    return false;
249	  }
250	
251	  // Remove every full row; the rows above drop down. Returns how many rows went.
252	  function clearLines() {
253	    var kept = board.filter(function (row) { return !row.every(Boolean); });
254	    var cleared = ROWS - kept.length;
255	    for (var i = 0; i < cleared; i++) kept.unshift(new Array(COLS).fill(''));
256	    board = kept;
257	    return cleared;
258	  }
259	
260	  function lock() {
261	    pieceCells(current).forEach(function (p) { board[p[0]][p[1]] = current.type; });
262	    current = null;
263	    var cleared = clearLines();
264	    lines += cleared;
265	    score += LINE_POINTS[cleared] * level;
266	    spawn();
267	  }
268	
269	  // One gravity step. The real timer and tick() both run exactly this. Returns true if the piece moved down.
270	  function gravityStep() {
271	    if (status !== 'running' || !current) return false;
272	    if (move(1, 0)) {
273	      current.lockTicks = 0;
274	      return true;
275	    }
276	    current.lockTicks++;
277	    if (current.lockTicks >= LOCK_TICKS) lock();
278	    return false;
279	  }
280	
281	  function gravity() {
282	    gravityStep();
283	    render();
284	  }
285	
286	  function stopTimer() {
287	    if (timer !== null) { clearInterval(timer); timer = null; }
288	  }
289	
290	  function startTimer() {
291	    stopTimer();
292	    timer = setInterval(gravity, GRAVITY_MS);
293	  }
294	
295	  // ---- Actions ----
296	  function input(action) {
297	    if (status !== 'running' || !current) return;
298	    if (action === 'left') shift(-1);
299	    else if (action === 'right') shift(1);
300	    else if (action === 'rotateCW') rotateCW();
301	    else if (action === 'softDrop') {
302	      if (gravityStep()) score += SOFT_DROP_POINTS;
303	    }
304	    else if (action === 'hardDrop') {
305	      while (move(1, 0)) score += HARD_DROP_POINTS;
306	      lock();
307	    }
308	    render();
309	  }
310	
311	  function toQueue(list) {
312	    return (Array.isArray(list) ? list : [])
313	      .map(function (t) { return String(t).toUpperCase(); })
314	      .filter(function (t) { return SHAPES.hasOwnProperty(t); });
315	  }
316	
317	  function newGame(list) {
318	    board = [];
319	    for (var r = 0; r < ROWS; r++) board.push(new Array(COLS).fill(''));
320	    bag = [];
321	    queue = toQueue(list);
322	    score = 0;
323	    level = 1;
324	    lines = 0;
325	    status = 'running';
326	    current = null;
327	    spawn();
328	    if (status === 'running') startTimer();
329	    render();
330	  }
331	
332	  function setQueue(list) {
333	    queue = toQueue(list);
334	    render();
335	  }
336	
337	  function setBoard(rows) {
338	    for (var r = 0; r < ROWS; r++) {
339	      var line = rows && typeof rows[r] === 'string' ? rows[r] : '';
340	      for (var c = 0; c < COLS; c++) {
341	        var ch = line.charAt(c).toUpperCase();
342	        board[r][c] = SHAPES.hasOwnProperty(ch) ? ch : '';
343	      }
344	    }
345	    render();
346	  }
347	
348	  function getBoard() {
349	    return board.map(function (row) {
350	      return row.map(function (t) { return t || '.'; }).join('');
351	    });
352	  }
353	
354	  function getState() {
355	    return {
356	      current: current ? { type: current.type, cells: pieceCells(current) } : null,
357	      next: queue.slice(),
358	      score: score,
359	      level: level,
360	      lines: lines,
361	      status: status
362	    };
363	  }
364	
365	  function tick(n) {
366	    var steps = n === undefined ? 1 : n;
367	    for (var i = 0; i < steps; i++) gravity();
368	  }
369	
370	  window.__tetris = {
371	    newGame: newGame,
372	    setQueue: setQueue,
373	    setBoard: setBoard,
374	    tick: tick,
375	    input: input,
376	    getBoard: getBoard,
377	    getState: getState
378	  };
379	
380	  var KEYS = { ArrowLeft: 'left', ArrowRight: 'right', ArrowUp: 'rotateCW', ArrowDown: 'softDrop', ' ': 'hardDrop', Spacebar: 'hardDrop' };
381	  document.addEventListener('keydown', function (e) {
382	    var action = KEYS[e.key];
383	    if (!action) return;
384	    e.preventDefault();
385	    input(action);
386	  });
387	  document.getElementById('new-game').addEventListener('click', function (e) {
388	    e.currentTarget.blur();
389	    newGame();
390	  });
391	
392	  newGame();
393	})();
394	</script>
395	</body>
396	</html>
